package com.documentverification.controller;
import com.documentverification.dao.*; import com.documentverification.model.*; import com.documentverification.util.CsrfUtil; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException; import java.util.List;
@WebServlet("/approval") public class ApprovalServlet extends HttpServlet{
 private final ApprovalDAO dao=new ApprovalDAO(); private final DocumentDAO docs=new DocumentDAO(); private final DocumentVersionDAO versions=new DocumentVersionDAO();
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String role=(String)r.getSession().getAttribute("role");if("ADMIN".equals(role)){s.sendError(403,"Admins cannot verify or view approval documents.");return;}long org=(Long)r.getSession().getAttribute("organizationId"),uid=(Long)r.getSession().getAttribute("userId");try{String a=r.getParameter("action");if("view".equals(a)){long id=Long.parseLong(r.getParameter("id"));Document d=docs.findById(org,id);if(d==null){s.sendError(404);return;}List<Document> queue=dao.findQueue(org,uid);boolean allowed=false;for(Document x:queue)if(x.getId()==id)allowed=true;if(!allowed){s.sendError(403);return;}r.setAttribute("document",d);r.setAttribute("versions",versions.findByDocument(org,id));r.setAttribute("history",dao.findHistory(org,id));r.setAttribute("csrfToken",CsrfUtil.token(r.getSession()));r.getRequestDispatcher("/WEB-INF/views/approver/document.jsp").forward(r,s);return;}r.setAttribute("queue",dao.findQueue(org,uid));r.setAttribute("csrfToken",CsrfUtil.token(r.getSession()));r.getRequestDispatcher("/WEB-INF/views/approver/queue.jsp").forward(r,s);}catch(Exception e){throw new ServletException("Unable to load approval queue",e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String role=(String)r.getSession().getAttribute("role");if("ADMIN".equals(role)){s.sendError(403,"Admins cannot verify or process documents.");return;}if(!CsrfUtil.valid(r)){s.sendError(403,"Invalid CSRF token");return;}try{long org=(Long)r.getSession().getAttribute("organizationId"),uid=(Long)r.getSession().getAttribute("userId"),doc=Long.parseLong(r.getParameter("documentId")),version=Long.parseLong(r.getParameter("versionId"));dao.process(org,uid,doc,version,r.getParameter("action"),r.getParameter("comment"),r.getRemoteAddr());s.sendRedirect(r.getContextPath()+"/approval");}catch(SecurityException e){s.sendError(403,e.getMessage());}catch(Exception e){throw new ServletException("Unable to process approval",e);}}
}
